    "code",
    "# 16 · Entrenamiento y evaluación reales, sin valores de F1 prefijados\nfrom pyspark.ml import Pipeline\nfrom pyspark.ml.feature import Tokenizer, HashingTF, IDF\nfrom pyspark.ml.classification import LogisticRegression\nfrom pyspark.ml.evaluation import MulticlassClassificationEvaluator\npipeline_demo = Pipeline(stages=[\n    Tokenizer(inputCol=\"texto\", outputCol=\"tokens\"),\n    HashingTF(inputCol=\"tokens\", outputCol=\"tf\", numFeatures=256),\n    IDF(inputCol=\"tf\", outputCol=\"features\"),\n    LogisticRegression(featuresCol=\"features\", labelCol=\"label\", maxIter=15, regParam=0.1)\n])\nmodelo_demo = pipeline_demo.fit(train_demo)\npred_demo = modelo_demo.transform(test_demo)\npred_demo.select(\"id_demo\", \"texto\", \"label\", \"prediction\").orderBy(\"id_demo\").show(truncate=False)\n# El PipelineModel aplica Tokenizer, HashingTF e IDF ya ajustado.\npred_demo.select(\"id_demo\", \"tokens\", \"tf\", \"features\").limit(2).show(truncate=70)\nassert pred_demo.count() == 8"
